INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "韦昭度", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：韦昭度。", "biography": null, "status": "draft", "id": "4d186310-6106-56bc-9a34-fa1d5d5d7894"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}, {"name": "朱珍", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的朱珍，在此段中为击退者。", "biography": null, "status": "draft", "id": "863c86d4-bcc1-57f7-a877-4c9d05eed8ca"}, {"name": "葛从周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的葛从周，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "26557449-8ad3-53a2-9cda-77849bf316c9"}, {"name": "丘弘礼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：丘弘礼。", "biography": null, "status": "draft", "id": "8356a161-4c47-52d1-a35f-49b759c4c92c"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "秦彦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：秦彦。", "biography": null, "status": "draft", "id": "720ca49a-19c0-563d-9b63-48f1e8e448f8"}, {"name": "张雄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张雄。", "biography": null, "status": "draft", "id": "c143e925-2fd8-5be6-abed-b89d550f0724"}, {"name": "冯弘铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：冯弘铎。", "biography": null, "status": "draft", "id": "7b1519f3-16d0-5251-a7f9-bf583e8dc0c9"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "毕师铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：毕师铎。", "biography": null, "status": "draft", "id": "f1541150-4966-5c04-9879-060cf391f2c2"}, {"name": "郑汉章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：郑汉章。", "biography": null, "status": "draft", "id": "6627883e-83a2-5c78-b77d-a62093d2195c"}, {"name": "李宗礼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：李宗礼。", "biography": null, "status": "draft", "id": "b8f1964a-f55a-56ef-9d9f-74bd32fe1866"}, {"name": "李涛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：李涛。", "biography": null, "status": "draft", "id": "6d85380a-8ee9-587e-a411-db6354d07b6d"}, {"name": "张浚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张浚。", "biography": null, "status": "draft", "id": "0ab7d6a4-deb7-5601-86cd-77e4e2b19fc2"}, {"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57