ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李茂贞授凤翔节度使", "start_year": 887, "end_year": 887, "time_original": "光启三年丙子；原文未重标月份", "dynasty": "唐", "description": "朝廷任李茂贞同平章事，充凤翔节度使。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "939ccf4a-1062-55b0-a98c-e8d39031f8d2"}, {"title": "韦昭度加守太保兼侍中", "start_year": 887, "end_year": 887, "time_original": "光启三年；具体月日未载", "dynasty": "唐", "description": "朝廷任韦昭度守太保、兼侍中。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "fdc030da-b9e2-5ff9-a745-22a6c635bd87"}, {"title": "朱全忠与朱瑄交恶", "start_year": 887, "end_year": 887, "time_original": "光启三年壬子前；具体月日未载", "dynasty": "唐", "description": "《通鉴》称朱全忠欲兼兖、郓，因朱瑄兄弟此前援己，遂以招诱宣武军士之说责备朱瑄；朱瑄回书不逊，两方生隙。", "phases": [], "location_name": "宣武、兖郓", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "83aa11c4-c4ed-5805-98a8-4e0637ee35a6"}, {"title": "朱珍葛从周袭曹州杀丘弘礼", "start_year": 887, "end_year": 887, "time_original": "光启三年壬子；原文未重标月份", "dynasty": "唐", "description": "朱全忠遣朱珍、葛从周袭曹州，壬子攻下，刺史丘弘礼被杀。", "phases": [], "location_name": "曹州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7b83fbd4-1217-5cee-bdd0-b88330b3541d"}, {"title": "朱全忠军与兖郓兵战于刘桥", "start_year": 887, "end_year": 887, "time_original": "曹州被攻后；具体月日未载", "dynasty": "唐", "description": "朱全忠军攻濮州，与兖、郓兵在刘桥交战；朱瑄、朱瑾逃脱。", "phases": [], "location_name": "濮州、刘桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b5e619c3-9f33-5260-a826-e03de1b6a874"}, {"title": "秦彦授张雄及部将告身", "start_year": 887, "end_year": 887, "time_original": "光启三年丁卯前；具体月日未载", "dynasty": "唐", "description": "秦彦希望借张雄军力，给张雄仆射告身，并给冯弘铎等部将尚书告身；张雄军与广陵民众以粮货交易，渐富而不愿作战，其后又帮助杨行密。", "phases": [], "location_name": "广陵、东塘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5698850d-e3e7-525f-a52e-44c99fa158f3"}, {"title": "杨行密于广陵城西败毕师铎郑汉章", "start_year": 887, "end_year": 887, "time_original": "光启三年丁卯；原文未重标月份", "dynasty": "唐", "description": "秦彦令毕师铎、郑汉章率军出城列阵。杨行密设粮帛诱敌并伏兵夹击，广陵军败，毕师铎、郑汉章逃脱。此后秦彦不再议出师。", "phases": [], "location_name": "广陵城西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "890d300c-986e-5c45-8e01-152cb9adf80d"}, {"title": "李涛主张杨行密出战", "start_year": 887, "end_year": 887, "time_original": "光启三年丁卯；原文未重标月份", "dynasty": "唐", "description": "李宗礼建议杨行密守寨，李涛反对退军并请为前锋；杨行密随后部署诱敌。", "phases": [], "location_name": "广陵城西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fcba752a-6c73-5ba9-b76a-bb79b6287af3"}, {"title": "张浚授兵部侍郎同平章事", "start_year": 887, "end_year": 887, "time_original": "光启三年九月；具体日未载", "dynasty": "唐", "description": "朝廷任张浚为兵部侍郎、同平章事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "7f998960-43e7-5133-a4ef-ed8b4ca10bc6"}, {"title": "高骈道院遭断供", "start_year": 887, "end_year": 887, "time_original": "光启三年九月甲戌前", "dynasty": "唐", "description": "高骈被拘于道院，秦彦供给极少，随侍人员陷入严重饥饿。", "phases": [], "location_name": "广陵道院", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43f4e1ee-51d8-5e4e-81d4-c443ef74a6e9"}, {"title": "秦彦命刘匡时杀高骈及家人", "start_year": 887, "end_year": 887, "time_original": "光启三年九月甲戌", "dynasty": "唐", "description": "秦彦因疑高骈厌胜及内应，又听王奉仙所谓“大人死”可解灾之言，命刘匡时杀高骈及其子弟甥侄，并合葬一坑。", "phases": [], "location_name": "广陵道院", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2a69c220-a948-559c-bec8-2e006df85121"}, {"title": "杨行密为高骈举哀", "start_year": 887, "end_year": 887, "time_original": "光启三年九月乙亥起三日", "dynasty": "唐", "description": "杨行密闻高骈被杀，率士卒穿丧服向广陵城哭悼三日。", "phases": [], "location_name": "广陵城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "341520c1-8821-51f9-a05b-d0b9724603d4"}, {"title": "朱瑄弟罕援濮州被擒斩", "start_year": 887, "end_year": 887, "time_original": "光启三年九月辛卯", "dynasty": "唐", "description": "朱珍攻濮州，朱瑄遣其弟罕率军来援；朱全忠在范迎击，罕被擒斩。", "phases": [], "location_name": "范、濮州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ead9ddfe-20bc-5ac6-9f6d-2b2a9384ed76"}, {"title": "郑汉章破张神剑高霸寨", "start_year": 887, "end_year": 887, "time_original": "光启三年十月；具体日未载", "dynasty": "唐", "description": "秦彦遣郑汉章攻张神剑、高霸营寨并破之；张神剑奔高邮，高霸奔海陵。", "phases": [], "location_name": "广陵外、高邮、海陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "08a076a7-a269-5f54-bc36-063edb9655d6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

